#!/bin/zsh
# 让 Codex 出 iPhone 版的设计图：和 Mac 版同一套设计语言，四个主要画面。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "当前目录有参考图 ref_mascot.png，是产品的吉祥物「小豆」：一只珍珠白的圆滚滚小仓鼠，脖子上挂白色耳机，耳机外圈有琥珀色灯环；还有 ui_home.png 和 ui_list_rows.png，是这款产品 Mac 版已经定稿的界面。请先看这三张图，然后使用内置的 image_gen 工具（把参考图一起传入，保持小豆长相和整体风格一致）生成一张横向的高保真 UI 设计稿：画面里并排摆着两台正面的 iPhone（无透视、竖屏、细边框、纯浅灰背景），每台显示一个界面。$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="这是 iOS 应用「豆仓」：连接一颗 AI 录音豆，把录音自动转成文字、整理成纪要和待办，并能向所有录音提问。它是 Mac 版的手机版，设计语言必须和 Mac 版一致：苹果 iOS 最新风格加乔纳森·艾维式的克制，留白舒服、字号层级清晰、圆角统一、细腻阴影。配色严格限定：暖白纸色背景（#F6F3EC）、卡片更白一点、石墨黑文字（#1A1A1A）、唯一强调色琥珀橙（#F2A33A），红色（#F0453A）只用于录音按钮；绝对不要蓝色、紫色、青色。文字全部是简体中文，像苹方，清晰可读、没有乱码。底部是 iOS 的浮动玻璃标签栏，四项：「总览」「录音」「知识库」「设备」，选中项是琥珀色；标签栏右上方悬着一个红色圆形的大录音按钮（白色圆点图标）。"
gen ios_home_list "左边一台是【总览】：顶部是小豆（中等大小）和大号问候「下午好」，下面一行灰字「有 3 件事等你处理」；接着一张卡片「接下来要做的」，三条带圆形勾选框的待办，每条下面小灰字写来自哪条录音；再一张卡片「最近的录音」，三行，每行左边琥珀色场景小方块、粗体标题、下面一行小灰字「16:52 · 0:44 · 会议」。右边一台是【录音】列表：大标题「录音」，下面搜索框，再下面一排胶囊筛选「全部 / 星标 / 有待办 / 有重点」，列表按「今天」「昨天」分组，每行：左边琥珀色场景小方块，粗体标题（AI 总结的一句话），标题下一行小信息「16:52 · 0:44 · 会议」加两个浅琥珀色小胶囊关键词，行尾是待办数和重点数的小图标。$S" &
gen ios_detail_stage "左边一台是【录音详情】：顶部返回箭头，大标题「周会确定新品发布时间与汇款率排查」，小灰字「11月12日 16:52 · 0:44 · 会议」，下面三段分段选择「纪要 / 文字稿 / 改写」，然后是「摘要」卡片、「要点」卡片（琥珀色小圆点列表）、「待办」卡片（勾选框）；屏幕底部悬着一条胶囊形播放条：琥珀色播放键、细密波形、时间、「1.25×」。右边一台是【正在录音的舞台】，这一屏是深色的：整屏石墨黑（#0E0E0F），顶部小红点和「正在录音 · soundcore Work」，中间是小豆戴着耳机在听（耳机灯环发琥珀光），下面是超大的细体计时「12:48」，再下面一条横贯屏幕的细密声波（暖白色竖线，最右几根是红色，中间有两根琥珀色标记线），声波下方一行实时字幕「我们先把下周三的发布时间定下来。」，底部一排三个圆形按钮：琥珀色「标重点」、中间灰色「暂停」、红色「结束」。$S" &
wait
